menv python -c "
import json
for fid in (5,6,7):
    m=json.load(open(f'data/{fid}/metadata.json')); el=m['end_time']-m['start_time']
    print(fid,'elapsed %.0f s'%el, {k:m.get(k) for k in ('slow_delay','fast_delay','delay')})
    for key in ('slow_setpoints','fast_setpoints','setpoints'):
        if key in m:
            v=m[key]; 
            try: print('   ',key, 'len', len(v), 'inner len', len(v[0]) if hasattr(v[0],'__len__') else 'scalar')
            except Exception as e: print('   ',key,type(v),str(e)[:60])
m=json.load(open('data/5/metadata.json')); ins=m.get('instruments',{}); print('instr keys',list(ins.keys())[:12])
for k in ('sr1','k_2400_tg','k_2400_bg','k_tg','k_bg'):
    if k in ins:
        d=ins[k]; print(k, {kk:d.get(kk) for kk in d if kk in ('sensitivity','time_constant','filter_slope','step','volt','inter_delay','nplci')})
        for p in ('parameters','params'):
            if p in d and isinstance(d[p],dict) and 'volt' in d[p]: print('   volt param:', {kk:vv for kk,vv in d[p]['volt'].items() if kk in ('step','inter_delay','value')})
"

